264	async function staticInventory(staticRoot: string): Promise<StaticInventory> {
265		const entries: Array<{ path: string; sha256: string }> = [];
266		const visit = async (directory: string): Promise<void> => {
267			for (const entry of (await readdir(directory, { withFileTypes: true })).sort((a, b) =>
268				a.name.localeCompare(b.name),
269			)) {
270				const path = join(directory, entry.name);
271				if (entry.isSymbolicLink())
272					throw new Error('Witness production-static inventory rejects symbolic links');
273				if (entry.isDirectory()) await visit(path);
274				else if (entry.isFile())
275					entries.push({
276						path: relative(staticRoot, path),
277						sha256: sha256(await readFile(path)),
278					});
279				else throw new Error('Witness production-static inventory contains a non-file entry');
280			}
281		};
282		await visit(staticRoot);
283		entries.sort((a, b) => a.path.localeCompare(b.path));
284		const application = entries.find((entry) => entry.path === 'index.html');
285		if (application === undefined) throw new Error('Witness production-static index is absent');
286		return {
287			files: entries.length,
288			digest: sha256(canonicalize(entries)),
289			applicationSha256: application.sha256,
290			serviceWorkers: entries.filter((entry) => entry.path === 'sw.js'),
291		};
292	}
