294	function safeStaticPath(staticRoot: string, requestUrl: string): string | null {
295		let pathname: string;
296		try {
297			pathname = decodeURIComponent(parseURL(requestUrl).pathname || '/');
298		} catch {
299			return null;
300		}
301		if (
302			pathname.includes('\\') ||
303			pathname.includes('\0') ||
304			pathname.split('/').some((part) => part === '..')
305		)
306			return null;
307		let relativePath = normalize(pathname);
308		while (relativePath.startsWith('/')) relativePath = relativePath.slice(1);
309		const file = resolve(staticRoot, relativePath === '' ? 'index.html' : relativePath);
310		const fromRoot = relative(staticRoot, file);
311		if (fromRoot === '..' || fromRoot.startsWith('../') || isAbsolute(fromRoot)) return null;
312		return file;
313	}
