315	async function readStaticFile(file: string): Promise<{ file: string; body: Buffer } | null> {
316		const details = await lstat(file).catch(() => null);
317		if (details === null || details.isSymbolicLink()) return null;
318		const resolved = details.isDirectory() ? join(file, 'index.html') : file;
319		const resolvedDetails = await lstat(resolved).catch(() => null);
320		if (resolvedDetails === null || !resolvedDetails.isFile() || resolvedDetails.isSymbolicLink())
321			return null;
322		return { file: resolved, body: await readFile(resolved) };
323	}
