325	export async function startStaticServer(
326		staticRoot: string,
327		options: {
328			profile?: 'current-witness' | 'canonical-t060';
329			diagnosticEvent?: (
330				event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
331			) => void;
332		} = {},
333	): Promise<{
334		origin: string;
335		close(): Promise<void>;
336		assertClean(): void;
337		requests(): string[];
338		ledger(): StaticResponseLedgerEntry[];
339	}> {
340		const failures: string[] = [];
341		const requests: string[] = [];
342		const ledger: StaticResponseLedgerEntry[] = [];
343		const server: Server = createServer((request, response) => {
344			void (async () => {
345				const parsedRequest = parseURL(request.url ?? '/');
346				const pathname = parsedRequest.pathname || '/';
347				const urlPath = `${pathname}${parsedRequest.search ?? ''}`;
348				options.diagnosticEvent?.({
349					source: 'static-server',
350					phase: 'start',
351					urlPath,
352					detail: {},
353				});
354				request.once('aborted', () =>
355					options.diagnosticEvent?.({
356						source: 'static-server',
357						phase: 'abort',
358						urlPath,
359						detail: {},
360					}),
361				);
362				requests.push(pathname);
363				const complete = (
364					status: number,
365					mime: string,
366					body: Buffer,
367					resolvedFile: string | null,
368				): void => {
369					response.once('finish', () => {
370						ledger.push({
371							method: request.method ?? 'GET',
372							pathname,
373							query: parsedRequest.search ?? '',
374							destination:
375								typeof request.headers['sec-fetch-dest'] === 'string'
376									? request.headers['sec-fetch-dest']
377									: '',
378							resolvedFile,
379							status,
380							mime,
381							bytes: body.length,
382							sha256: sha256(body),
383						});
384						options.diagnosticEvent?.({
385							source: 'static-server',
386							phase: 'finish',
387							urlPath,
388							detail: { status, bytes: body.length, sha256: sha256(body), mime },
389						});
390					});
391					response.writeHead(status, {
392						...(options.profile === 'canonical-t060'
393							? {}
394							: { 'cache-control': 'no-store' }),
395						'content-type':
396							options.profile === 'canonical-t060' &&
397							(mime === 'text/html' || mime === 'text/javascript')
398								? `${mime}; charset=utf-8`
399								: mime,
400					});
401					response.end(body);
402				};
403				const requestedFile = safeStaticPath(staticRoot, request.url ?? '/');
404				if (requestedFile === null) {
405					complete(400, 'text/plain', Buffer.from('invalid path'), null);
406					return;
407				}
408				let result = await readStaticFile(requestedFile);
409				if (result === null && request.headers['sec-fetch-dest'] === 'document')
410					result = await readStaticFile(join(staticRoot, 'index.html'));
411				if (result === null) {
412					complete(404, 'text/plain', Buffer.from('not found'), null);
413					return;
414				}
415				complete(
416					200,
417					CONTENT_TYPES[extname(result.file)] ?? 'application/octet-stream',
418					result.body,
419					relative(staticRoot, result.file),
420				);
421			})().catch((error: unknown) => {
422				failures.push(error instanceof Error ? error.message : String(error));
423				if (!response.headersSent) response.writeHead(500, { 'content-type': 'text/plain' });
424				response.end('static server failure');
425			});
426		});
427		server.requestTimeout = 15_000;
428		server.headersTimeout = 10_000;
429		await new Promise<void>((resolveListen, rejectListen) => {
430			server.once('error', rejectListen);
431			server.listen(0, '127.0.0.1', () => {
432				server.off('error', rejectListen);
433				resolveListen();
434			});
435		});
436		const address = server.address();
437		if (address === null || typeof address === 'string') throw new Error('static origin is absent');
438		const origin = stringifyParsedURL({
439			protocol: 'http:',
440			host: `127.0.0.1:${(address as AddressInfo).port}`,
441		});
442		return {
443			origin,
444			close: async () =>
445				void (await new Promise<void>((resolveClose, rejectClose) => {
446					server.close((error) =>
447						error === undefined ? resolveClose() : rejectClose(error),
448					);
449				})),
450			assertClean: () => {
451				if (failures.length > 0)
452					throw new Error(`Witness production-static server failed: ${failures.join('; ')}`);
453			},
454			requests: () => [...requests],
455			ledger: () => structuredClone(ledger),
456		};
457	}
