500	async function exactLegacyMainPrecacheResponses(
501		laneRoot: string,
502		ledger: StaticResponseLedgerEntry[],
503	): Promise<LegacyMainPrecacheResponse[]> {
504		const responses: LegacyMainPrecacheResponse[] = [];
505		for (const expected of BASELINE_REACT_MAIN_ASSETS) {
506			const matches = ledger.filter(
507				(entry) =>
508					entry.pathname === expected.pathname &&
509					entry.query === BASELINE_REACT_CACHE_BUST_QUERY,
510			);
511			if (matches.length !== 1)
512				throw new Error(
513					`React legacy main precache response cardinality differs: ${expected.pathname}${BASELINE_REACT_CACHE_BUST_QUERY}`,
514				);
515			const [entry] = matches;
516			const body = await readFile(join(laneRoot, expected.resolvedFile));
517			if (
518				entry === undefined ||
519				entry.method !== 'GET' ||
520				entry.destination !== 'empty' ||
521				entry.resolvedFile !== expected.resolvedFile ||
522				entry.status !== 200 ||
523				entry.mime !== expected.mime ||
524				entry.bytes !== body.length ||
525				entry.sha256 !== sha256(body)
526			)
527				throw new Error(
528					`React legacy main precache response differs: ${expected.pathname}${BASELINE_REACT_CACHE_BUST_QUERY}`,
529				);
530			responses.push({
531				method: 'GET',
532				pathname: entry.pathname,
533				query: BASELINE_REACT_CACHE_BUST_QUERY,
534				destination: 'empty',
535				resolvedFile: expected.resolvedFile,
536				status: 200,
537				mime: entry.mime,
538				bytes: entry.bytes,
539				sha256: entry.sha256,
540				urlPath: `${entry.pathname}${entry.query}`,
541				source: 'production-static-origin',
542			});
543		}
544		return responses;
545	}
