547	function exactNextPrerenderPayloadEvidence(
548		laneRoot: string,
549		ledger: StaticResponseLedgerEntry[],
550		input: NextPrerenderPayloadInput,
551	): Extract<WitnessNextPrerenderPayloadEvidence, { state: 'exact-lane-bound-next-prerender' }> {
552		const failed = ledger.filter((entry) => entry.status !== 200);
553		if (failed.length !== 0)
554			throw new Error(
555				`KilledByGoogle local production-static response failed: ${canonicalize(failed)}`,
556			);
557		const matches = ledger.filter(
558			(entry) => entry.pathname === input.dataRoute && entry.query === '',
559		);
560		if (matches.length !== 1)
561			throw new Error(
562				`KilledByGoogle prerender response cardinality differs: ${input.dataRoute}`,
563			);
564		const [entry] = matches;
565		const stagedFile = join(laneRoot, input.stagedPath);
566		if (
567			entry === undefined ||
568			entry.method !== 'GET' ||
569			entry.destination !== 'empty' ||
570			entry.resolvedFile !== input.stagedPath ||
571			entry.status !== 200 ||
572			entry.mime !== 'application/json' ||
573			entry.bytes !== input.payload.bytes ||
574			entry.sha256 !== input.payload.sha256
