627	async function expectedPhonecatOrdering(laneRoot: string): Promise<{
628		names: string[];
629		datasetSha256: string;
630		orderSha256: string;
631	}> {
632		const dataset = await readFile(join(laneRoot, 'phones/phones.json'));
633		const phones = JSON.parse(dataset.toString('utf8')) as Array<{ name?: unknown }>;
634		if (
635			phones.length !== 20 ||
636			phones.some((phone) => typeof phone.name !== 'string' || phone.name.length === 0)
637		)
638			throw new Error('PhoneCat immutable phone-name dataset differs');
639		const names = phones
640			.map((phone, sourceIndex) => ({ name: phone.name as string, sourceIndex }))
641			.sort((left, right) => {
642				const leftName = left.name.toLowerCase();
643				const rightName = right.name.toLowerCase();
644				if (leftName < rightName) return -1;
645				if (leftName > rightName) return 1;
646				return left.sourceIndex - right.sourceIndex;
647			})
648			.map((phone) => phone.name);
649		return {
650			names,
651			datasetSha256: sha256(dataset),
652			orderSha256: sha256(canonicalize(names)),
653		};
654	}
