1045	async function execute(
1046		command: string,
1047		args: string[],
1048		cwd: string,
1049		environment: NodeJS.ProcessEnv,
1050	): Promise<void> {
1051		await new Promise<void>((resolvePromise, reject) => {
1052			const child = spawn(command, args, { cwd, env: environment, stdio: 'inherit' });
1053			child.once('error', reject);
1054			child.once('exit', (code) =>
1055				code === 0 ? resolvePromise() : reject(new Error(`${command} exited ${code}`)),
1056			);
1057		});
1058	}
