1060	async function fileCount(directory: string): Promise<number> {
1061		let count = 0;
1062		for (const entry of await readdir(directory, { withFileTypes: true })) {
1063			if (entry.isDirectory()) count += await fileCount(join(directory, entry.name));
1064			else if (entry.isFile()) count += 1;
1065		}
1066		return count;
1067	}
