234		const integrated = { ...aggregate, fixtures: nextFixtures };
235		const expectedKind =
236			current.kind === 'react-zero-sw-reconciliation'
237				? 'react-zero-sw-reconciliation'
238				: current.kind === 'next-candidate'
239					? 'next-candidate'
240					: current.kind === 'react-candidate'
