352		const markdown = await readFile(join(output, 'receipt.md'), 'utf8');
353		if (markdown !== renderWitnessAngularRealworldReceipt(receipt))
354			throw new Error('Angular RealWorld Witness human receipt differs');
355		const serialized = JSON.stringify(receipt);
356		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
357			throw new Error('Angular RealWorld Witness receipt leaks host identity');
358		return receipt;
