46		repository: 'https://github.com/react-boilerplate/react-boilerplate',
47		revision: 'd19099afeff64ecfb09133c06c1cb18c0d40887e',
48		archiveSha256: 'd6ca60a3c8881ae2be26a8d04e00da4d922a6653f8512f2b12ac55d48f2ce2d5',
49		license: 'MIT',
