60	async function files(directory: string): Promise<string[]> {
61		const output: string[] = [];
62		for (const entry of await readdir(directory, { withFileTypes: true })) {
63			const path = join(directory, entry.name);
64			if (entry.isDirectory()) output.push(...(await files(path)));
65			else if (entry.isFile()) output.push(path);
66		}
67		return output.sort();
68	}
