70	async function protectedHashes(): Promise<void> {
71		for (const binding of Object.values(REACT_BOILERPLATE_ZERO_SW_SUPERSEDES))
72			if (sha256(await readFile(join(root, binding.path))) !== binding.sha256)
73				throw new Error(`Protected evidence silently rebound: ${binding.path}`);
74	}
