76	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
77		const lanes = join(stageRoot, 'lanes');
78		await rm(lanes, { recursive: true, force: true });
79		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
80		for (const lane of ['baseline', 'migrated'] as const) {
81			if (!(await exists(sourceOutputs[lane])))
82				throw new Error(`React Boilerplate zero-SW ${lane} production output is absent`);
83			await mkdir(dirname(staged[lane]), { recursive: true });
84			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
85		}
86		return staged;
87	}
