89	async function executeRuns(
90		lanes: Record<'baseline' | 'migrated', string>,
91	): Promise<WitnessReactBoilerplateZeroSwRun[]> {
92		const runs: WitnessReactBoilerplateZeroSwRun[] = [];
93		for (const lane of ['baseline', 'migrated'] as const)
94			for (const pass of [1, 2] as const) {
95				const raw = await executeReactBoilerplateZeroSwWitnessRun({
96					lane,
97					pass,
98					laneRoot: lanes[lane],
99					receiptRoot: join(stageRoot, 'receipts'),
100				});
101				const run = raw as WitnessReactBoilerplateZeroSwRun;
102				if (run.semanticDigest !== witnessReactBoilerplateZeroSwRawDigest(run))
103					throw new Error(
104						`React Boilerplate zero-SW ${lane} pass ${pass} raw digest differs`,
105					);
106				runs.push({ ...run, behaviorDigest: witnessReactBoilerplateZeroSwBehaviorDigest(run) });
107			}
108		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
109			throw new Error('React Boilerplate zero-SW baseline/target behavior parity differs');
110		return runs;
111	}
