113	async function semanticMutation(
114		laneRoot: string,
115		behaviorDigest: string,
116	): Promise<WitnessReactBoilerplateZeroSwReceipt['mutations']['semantic']> {
117		const expected = Buffer.from('Beginnen Sie Ihr nächstes React Projekt in Sekunden');
118		const candidates: Array<{ path: string; offset: number }> = [];
119		for (const path of await files(laneRoot)) {
120			const bytes = await readFile(path);
121			const offset = bytes.indexOf(expected);
122			if (offset >= 0) {
123				if (bytes.lastIndexOf(expected) !== offset)
124					throw new Error('German heading semantic seam is not unique within its file');
125				candidates.push({ path, offset });
126			}
127		}
128		if (candidates.length !== 1)
129			throw new Error('German heading semantic seam is not unique across target output');
130		const target = candidates[0]!;
131		const before = await readFile(target.path);
132		const mutated = Buffer.from(before);
133		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
134		const beforeSha256 = sha256(before);
135		const mutatedSha256 = sha256(mutated);
136		let intendedFailure = false;
137		try {
138			await writeFile(target.path, mutated);
139			try {
140				await executeReactBoilerplateZeroSwWitnessRun({
141					lane: 'migrated',
142					pass: 1,
143					laneRoot,
144					receiptRoot: join(stageRoot, 'semantic-mutation-receipt'),
145				});
146			} catch (error) {
147				const message = error instanceof Error ? error.message : String(error);
148				intendedFailure = message.includes(
149					'Beginnen Sie Ihr nächstes React Projekt in Sekunden',
150				);
151			}
152		} finally {
153			await writeFile(target.path, before);
154		}
155		const afterRestoreSha256 = sha256(await readFile(target.path));
156		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
157			throw new Error('German heading mutation was not exact red and byte-restored');
158		const restoredRaw = await executeReactBoilerplateZeroSwWitnessRun({
159			lane: 'migrated',
160			pass: 1,
161			laneRoot,
162			receiptRoot: join(stageRoot, 'semantic-restoration-receipt'),
163		});
164		const restored = restoredRaw as WitnessReactBoilerplateZeroSwRun;
165		if (witnessReactBoilerplateZeroSwBehaviorDigest(restored) !== behaviorDigest)
166			throw new Error('German heading restored browser behavior differs');
167		return {
168			failure: 'witness-semantic-assertion',
169			intendedFailure: true,
170			path: relative(laneRoot, target.path),
171			beforeSha256,
172			mutatedSha256,
173			afterRestoreSha256,
174			restoredByteIdentically: true,
175			restoredRun: 'pass',
176		};
177	}
178	
179	async function serviceWorkerMutation(): Promise<
180		WitnessReactBoilerplateZeroSwReceipt['mutations']['serviceWorker']
181	> {
182		const laneRoot = join(root, '.versionless/stage/react-boilerplate-v4-zero-sw/mutation-output');
183		if (!(await exists(join(laneRoot, 'sw.js'))))
184			throw new Error('Service-worker mutation output is absent');
185		let intendedFailure = false;
186		try {
187			await executeReactBoilerplateZeroSwWitnessRun({
188				lane: 'baseline',
189				pass: 1,
190				laneRoot,
191				receiptRoot: join(stageRoot, 'service-worker-mutation-receipt'),
192			});
193		} catch (error) {
194			const message = error instanceof Error ? error.message : String(error);
195			intendedFailure = message.includes('zero-service-worker policy assertion failed');
196		}
197		if (!intendedFailure)
198			throw new Error('Service-worker mutation did not make the runtime zero-SW guard red');
199		return {
200			failure: 'zero-service-worker-policy-assertion',
201			intendedFailure: true,
202			observedOutputFiles: ['sw.js'],
203			observedRegistrationOrWorker: true,
204		};
205	}
206	
207	async function writeFixtureReceipt(
208		runs: WitnessReactBoilerplateZeroSwRun[],
209		mutations: WitnessReactBoilerplateZeroSwReceipt['mutations'],
210	): Promise<ReactBoilerplateZeroSwReceipt> {
211		const artifactsRoot = join(fixtureEvidence, 'artifacts');
212		const journeyPath = join(artifactsRoot, 'witness-journeys.json');
213		const mutationPath = join(artifactsRoot, 'witness-mutations.json');
214		await writeFile(journeyPath, `${canonicalize(runs)}\n`, { flag: 'wx' });
215		await writeFile(mutationPath, `${canonicalize(mutations)}\n`, { flag: 'wx' });
216		const buildPath = join(artifactsRoot, 'build.json');
217		const receipt = {
218			schemaVersion: 'versionless.receipt.v1' as const,
219			runId: REACT_BOILERPLATE_ZERO_SW_RUN_ID,
220			fixture: REACT_BOILERPLATE_ZERO_SW_FIXTURE,
221			source,
222			tooling: {
223				legacyNode: '16.20.2',
224				targetNode: '24.15.0',
225				legacyBundler: 'webpack-4.30.0',
226				targetBundler: 'Vite-8.0.16',
227				witness: 'direct-linked-local-0.8.0',
228			},
229			consent: [
230				{
231					id: 'T693-local-reconciliation',
232					purpose: 'reuse already-ingested immutable fixture and local dependencies',
233					mode: 'consented' as const,
234				},
235			],
236			migration: {
237				file: 'app/app.js + internals/webpack/webpack.prod.babel.js',
238				transform: 'react-boilerplate-zero-service-worker-profile',
239				edits: 3,
240				dependency: {
241					name: 'offline-plugin',
242					from: 'executed-and-registered',
243					to: 'retained-unused-unshipped',
244					license: 'MIT',
245				},
246				lockPatch: 'none; dependency closure retained',
247			},
248			verification: {
249				result: 'pass' as const,
250				builds: 'pass' as const,
251				journeys: 'pass' as const,
